function metricUnit(key){const base=key.endsWith("_paired_delta")?key.slice(0,-13):key;if(ratioMetricKeys.has(base))return key.endsWith("_paired_delta")?"百分点":"%";if(speedMetricKeys.has(base))return "Mbps";if(powerMetricKeys.has(base))return "W";return "";}
function displayMetric(key,value,{unit=true}={}){if(value===null||value===undefined||value==="")return "—";if(typeof value==="boolean")return value?"是":"否";const number=Number(value);if(!Number.isFinite(number))return String(value);const delta=key.endsWith("_paired_delta"),base=delta?key.slice(0,-13):key;let converted=number;if(ratioMetricKeys.has(base))converted=number*100;else if(speedMetricKeys.has(base))converted=number/1e6;const formatted=new Intl.NumberFormat("zh-CN",{maximumFractionDigits:ratioMetricKeys.has(base)?2:3}).format(converted),symbol=unit?metricUnit(key):"";return `${delta&&converted>0?"+":""}${formatted}${symbol?(symbol==="%"||symbol==="百分点"?"":" ")+symbol:""}`;}
