const duration=(x)=>{if(x===null||x===undefined||!Number.isFinite(Number(x)))return "—";let n=Math.max(0,Math.round(Number(x)));return `${Math.floor(n/3600)}时${Math.floor(n%3600/60)}分${n%60}秒`;};
