function pendingRequest(storageKey,payload){const serialized=JSON.stringify(payload);let saved;try{saved=JSON.parse(localStorage.getItem(storageKey)||"null");}catch{}if(saved&&typeof saved.request_id==="string"&&JSON.stringify(saved.payload)===serialized)return saved;const next={request_id:id(),payload:JSON.parse(serialized)};localStorage.setItem(storageKey,JSON.stringify(next));return next;}
function clearPendingRequest(storageKey,requestId){try{const saved=JSON.parse(localStorage.getItem(storageKey)||"null");if(saved?.request_id===requestId)localStorage.removeItem(storageKey);}catch{}}
function notify(message,bad=false){const el=$("toast");el.textContent=message;el.classList.toggle("bad",bad);el.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.hidden=true,6000);}
async function api(path,method="GET",body){const options={method,headers:{Accept:"application/json"}};if(body!==undefined){options.headers["Content-Type"]="application/json";options.body=JSON.stringify(body);}let response;try{response=await fetch(path,options);}catch(error){throw new Error("无法连接本地服务："+error.message);}let data;try{data=await response.json();}catch{throw new Error(`服务返回非 JSON 数据（HTTP ${response.status}）`);}if(!response.ok)throw new Error(data.error||`请求失败（HTTP ${response.status}）`);return data;}
function setPage(page){state.page=page;for(const el of document.querySelectorAll(".page")){const active=el.id==="page-"+page;el.hidden=!active;el.classList.toggle("active",active);}for(const button of document.querySelectorAll("[data-page]"))button.setAttribute("aria-current",button.dataset.page===page?"page":"false");try{history.replaceState(null,"",`#${page}`);}catch{}if(page==="monitor")refreshMonitor();if(page==="test")refreshResources();if(page==="compare")refreshRuns();}
function options(select,items,label,value,placeholder="请选择"){const previous=select.value;select.replaceChildren();select.add(new Option(placeholder,""));for(const item of items)select.add(new Option(label(item),String(value(item))));if([...select.options].some((x)=>x.value===previous))select.value=previous;}
function cat(name){const x=state.catalog[name];return Array.isArray(x)?x:Object.values(x||{});}
function lookup(collection,key){return cat(collection).find((item)=>String(item.id??item.kind??item.name)===String(key));}
function itemLabel(collection,key){const found=lookup(collection,key);return found?.label||found?.name||labels[key]||key;}
function setPath(object,path,value){const parts=path.split(".");let target=object;for(let i=0;i<parts.length-1;i++)target=target[parts[i]];target[parts.at(-1)]=value;}
function getPath(object,path){return path.split(".").reduce((x,k)=>x?.[k],object);}
function field(path,value,allowed){const name=path.split(".").at(-1);const label=fieldNames[name]||name;let input;if(allowed){input=`<select data-path="${esc(path)}">${allowed.map((a)=>`<option value="${esc(a)}" ${String(a)===String(value)?"selected":""}>${esc(labels[a]||a)}</option>`).join("")}</select>`;}else if(Array.isArray(value)){input=`<input data-path="${esc(path)}" data-array="true" type="text" value="${esc(value.join(", "))}">`;}else if(typeof value==="number"){input=`<input data-path="${esc(path)}" type="number" step="any" value="${esc(value)}">`;}else if(typeof value==="boolean"){input=`<select data-path="${esc(path)}"><option value="true" ${value?"selected":""}>是</option><option value="false" ${!value?"selected":""}>否</option></select>`;}else{input=`<input data-path="${esc(path)}" type="text" value="${esc(value)}">`;}return `<label class="field">${esc(label)}${input}</label>`;}
function fieldGroup(prefix,keys,allowed={}){return `<div class="field-grid">${keys.filter((key)=>Object.hasOwn(getPath(state.config,prefix)||{},key)).map((key)=>field(`${prefix}.${key}`,getPath(state.config,`${prefix}.${key}`),allowed[key])).join("")}</div>`;}
