function onConfigInput(target){if(!state.config)return;if(target.dataset.sceneRole){selectSceneRole(target.dataset.sceneRole,target.value);return;}if(target.hasAttribute("data-training-scene")){state.trainingSceneId=target.value;localStorage.setItem("satellite-workbench-training-scene",target.value);return;}const path=target.dataset.path;if(path){let value=target.value;const old=getPath(state.config,path);if(target.dataset.array){value=value.split(/[，,\s]+/).filter(Boolean).map(Number);}else if(typeof old==="number"){value=value===""?null:Number(value);}else if(typeof old==="boolean"){value=value==="true";}const previousLayout=state.config.network.transformer_layout;setPath(state.config,path,value);if(path==="network.temporal_mode"||path==="network.graph_mode"){configureExperimentEncoding(state.config,path,value);renderConfigForm();}else if(path==="training.alpha_mode"){renderConfigForm();}else if(path==="network.transformer_layout"){state.config.network.temporal_mode="none";state.config.network.graph_mode="none";const preset=lookup("network_presets",value);if(preset?.state_features){state.config.state.features=clone(preset.state_features);state.config.state.context_level=preset.context_level||"none";if(preset.demand_visibility)state.config.state.demand_visibility=preset.demand_visibility;}else if(previousLayout==="tsac_natural_context"||previousLayout==="tsac_32_context"){state.config.state.features=clone(state.defaults.state.features);state.config.state.context_level="none";}if(value==="tsac_natural_context"){syncNaturalFeatures(state.config);if(preset){state.config.algorithm=preset.algorithm;state.config.network.temporal_mode="none";state.config.network.graph_mode="none";Object.assign(state.config.network,clone(preset.network));if(preset.reward_preset)state.config.reward.preset=preset.reward_preset;if(preset.scene_order)state.config.training.scene_order=preset.scene_order;}}renderConfigForm();}else if(path==="state.context_level"){if(value!=="compact")state.config.network.temporal_mode="none";if(value!=="full")state.config.network.graph_mode="none";if(state.config.network.transformer_layout==="tsac_natural_context")syncNaturalFeatures(state.config);renderConfigForm();}else if(path==="environment.profile"){clearIncompatibleSceneSelections();renderConfigForm();}else if(path==="telemetry.mode"){renderConfigForm();}}
else if(target.dataset.feature){if(state.config.network.transformer_layout==="tsac_natural_context")return;const key=target.dataset.feature;let f=state.config.state.features;state.config.state.features=target.checked?[...f,key]:f.filter((x)=>x!==key);renderConfigForm();}
else if(target.dataset.network){const oldLayout=state.config.network.transformer_layout;state.config.network.kind=target.dataset.network;if(target.dataset.network!=="transformer"){state.config.network.temporal_mode="none";state.config.network.graph_mode="none";state.config.network.transformer_layout="scalar_tokens";if(oldLayout==="tsac_natural_context"||oldLayout==="tsac_32_context"){state.config.state.features=clone(state.defaults.state.features);state.config.state.context_level="none";}}renderConfigForm();}
else if(target.dataset.term){const key=target.dataset.term;let t=state.config.reward.terms;state.config.reward.preset="custom";state.config.reward.terms=target.checked?[...t,{id:key,weight:Number(document.querySelector(`[data-term-weight="${CSS.escape(key)}"]`)?.value||1),scale:Number(document.querySelector(`[data-term-scale="${CSS.escape(key)}"]`)?.value||1),timing:lookup("reward_terms",key)?.timing||"step"}]:t.filter((x)=>x.id!==key);renderConfigForm();}
else if(target.dataset.termWeight||target.dataset.termScale){const key=target.dataset.termWeight||target.dataset.termScale;const term=state.config.reward.terms.find((x)=>x.id===key);if(term){term[target.dataset.termWeight?"weight":"scale"]=Number(target.value);state.config.reward.preset="custom";}}
saveDraft();scheduleValidation();}
function moveFeature(key,direction){if(state.config.network.transformer_layout==="tsac_natural_context")return;const list=state.config.state.features,from=list.indexOf(key),to=from+direction;if(from<0||to<0||to>=list.length)return;[list[from],list[to]]=[list[to],list[from]];renderConfigForm();saveDraft();scheduleValidation();}
function applyNetworkPreset(presetId){
  const preset=lookup("network_presets",presetId);
  if(!preset){notify("服务未提供此网络预设",true);return;}
  state.config.algorithm=preset.algorithm;state.config.network.temporal_mode="none";state.config.network.graph_mode="none";
  state.config.state.features=clone(preset.state_features);
  state.config.state.context_level=preset.context_level||"none";
  if(preset.demand_visibility)state.config.state.demand_visibility=preset.demand_visibility;
  Object.assign(state.config.network,clone(preset.network));
  if(presetId==="tsac_natural_context"){
    syncNaturalFeatures(state.config);
    if(preset.reward_preset)state.config.reward.preset=preset.reward_preset;
    if(preset.scene_order)state.config.training.scene_order=preset.scene_order;
  }
  renderConfigForm();saveDraft();scheduleValidation();
  notify(`已套用${preset.label||presetId}，请检查实际场景、预算和动作掩码`);
}
