function saveDraft(){try{localStorage.setItem("satellite-workbench-draft-v1",JSON.stringify(state.config));}catch{}}
function loadDraft(){try{const raw=localStorage.getItem("satellite-workbench-draft-v1");return raw?JSON.parse(raw):null;}catch{return null;}}
function scheduleValidation(){state.validationSeq++;state.validated=null;state.networkModel=null;state.networkSummary=null;$("state-dim").textContent="—";$("state-layout").innerHTML="<li>等待服务端校验实际拼接顺序</li>";$("parameter-count").textContent="参数量待校验";renderNetworkGraph();$("config-state").textContent="有未检查更改";$("action-mask-summary").textContent=labels[state.config.environment?.action_mask||"none"]||"—";$("network-layout-summary").textContent=state.config.network?.kind==="transformer"?`${labels[state.config.network.transformer_layout||"scalar_tokens"]||"—"} · 待校验`:"当前网络不使用 Transformer 令牌";clearTimeout(state.validationTimer);state.validationTimer=setTimeout(()=>validate(false),500);}
async function validate(showToast=true){if(!state.config)return false;const seq=++state.validationSeq,raw=clone(state.config),snapshot=JSON.stringify(raw);try{const data=await api("/api/validate","POST",raw);if(seq!==state.validationSeq||snapshot!==JSON.stringify(state.config))return false;state.validated=data;state.config=data.config||state.config;saveDraft();renderSummary(data.summary||{},data.model||{});$("config-state").textContent="校验通过";$("config-state").classList.remove("bad");$("config-errors").textContent="配置与模型构建检查通过。";$("config-errors").className="notice good";$("config-warnings").innerHTML=(data.summary?.warnings||[]).map((x)=>`<p class="field-note warn">${esc(x)}</p>`).join("");if(showToast)notify("配置校验通过");return true;}catch(error){if(seq!==state.validationSeq||snapshot!==JSON.stringify(state.config))return false;state.validated=null;$("config-state").textContent="校验失败";$("config-state").classList.add("bad");$("config-errors").textContent=error.message;$("config-errors").className="notice bad";if(showToast)notify(error.message,true);return false;}}
function readableLayerType(type){return {Linear:"全连接",Conv1d:"一维卷积",ReLU:"ReLU 激活",GELU:"GELU 激活",Tanh:"Tanh 激活",Dropout:"Dropout",MultiheadAttention:"多头注意力",LayerNorm:"层归一化",AdaptiveAvgPool1d:"自适应池化",Flatten:"展平",PositionalParameter:"位置参数",TokenAssembly:"令牌拼接",FirstTokenPool:"首令牌读取"}[type]||type||"计算层";}
