function renderCompareChoices(){const old=new Set([...document.querySelectorAll(".compare-choice:checked")].map((x)=>x.value));$("compare-choices").innerHTML=state.runs.map((run)=>`<label><input type="checkbox" class="compare-choice" value="${esc(run.run_id)}" ${old.has(run.run_id)?"checked":""}> <strong>${esc(run.name||run.run_id)}</strong><br><span class="small muted">${esc(labels[run.stage]||run.stage||"—")} · ${esc(labels[run.algorithm]||run.algorithm||"—")} · ${esc(run.kind||"训练")}</span></label>`).join("")||"<div class=\"notice muted\">暂无运行。</div>";}
