function beamIdentity(beam){return `原始波束 ID ${beam.original_index??"—"} · 处理序号 ${beam.beam_id??"—"}`;}
function traceAction(action){if(!action||typeof action!=="object")return "未记录";const fields=[["group","组"],["freq","频率槽起点"],["slots","连续槽数"],["power_w","功率 / W"],["charged_power_w","预算记账功率 / W"]];const parts=fields.filter(([key])=>action[key]!==undefined&&action[key]!==null).map(([key,label])=>`${label} ${action[key]}`);return parts.length?parts.join(" · "):JSON.stringify(action);}
