function renderTraceStep(){const trace=state.currentTrace,index=Math.max(0,Math.min(state.traceIndex,trace.length-1));state.traceIndex=index;$("trace-step").max=String(Math.max(0,trace.length-1));$("trace-step").value=String(index);$("trace-position").textContent=trace.length?`${index+1} / ${trace.length}`:"—";$("trace-prev").disabled=!trace.length||index===0;$("trace-next").disabled=!trace.length||index===trace.length-1;$("trace-step").disabled=!trace.length;if(!trace.length){$("trace-view").innerHTML='<div class="empty-state">此场景没有逐步动作记录</div>';return;}const row=trace[index],radiated=cumulativeTracePower(trace,index,"power_w"),charged=cumulativeTracePower(trace,index,"charged_power_w");$("trace-view").innerHTML=`<div class="trace-step-card"><h4>记录步骤 ${esc(row.step??"—")} · 处理序号 ${esc(row.beam_id??"—")}${row.policy?` · ${esc(row.policy)}`:""}</h4><dl><dt>请求动作</dt><dd>${esc(traceAction(row.requested_action??row.requested))}</dd><dt>实际动作</dt><dd>${esc(traceAction(row.actual_action??row.actual))}</dd><dt>本步奖励</dt><dd>${esc(txt(row.reward))}</dd><dt>本步需求</dt><dd>${esc(displayMetric("required_bps",row.beam_service_step?.required_bps))}</dd><dt>本步容量</dt><dd>${esc(displayMetric("capacity_bps",row.beam_service_step?.capacity_bps))}</dd><dt>有效服务量</dt><dd>${esc(displayMetric("effective_served_bps",row.beam_service_step?.effective_served_bps))}</dd><dt>容量/需求</dt><dd>${esc(txt(row.beam_service_step?.capacity_demand_ratio))}</dd><dt>本步SI</dt><dd>${esc(displayMetric("si",row.beam_service_step?.si))}</dd><dt>本步SGM</dt><dd>${esc(displayMetric("sgm",row.beam_service_step?.sgm))}</dd><dt>累计实际辐射功率</dt><dd>${radiated===null?"该轨迹未完整记录":esc(displayMetric("radiated_power_w",radiated))}</dd><dt>累计预算记账功率</dt><dd>${charged===null?"该轨迹未完整记录":esc(displayMetric("power_w",charged))}</dd></dl><details open><summary>奖励分项原始记录</summary><pre>${esc(JSON.stringify(row.reward_terms??{},null,2))}</pre></details><details><summary>该步全部原始字段</summary><pre>${esc(JSON.stringify(row,null,2))}</pre></details></div>`;}
function renderTrace(scene){const key=`${$("evaluation-run").value}:${scene.scene_id||scene.id||scene.name}`,trace=Array.isArray(scene.trace)?scene.trace:Array.isArray(scene.traces)?scene.traces:[];if(state.traceSceneKey!==key){state.traceSceneKey=key;state.traceIndex=0;}state.currentTrace=trace;$("trace-raw").textContent=JSON.stringify(trace,null,2);renderTraceStep();}
