function drawBaselineBars(container,beams,baselineBeams,name){const rows=beams.map((b,i)=>({identity:beamIdentity(b),required:Number(b.required_bps),model:Number(b.rate_bps),baseline:Number(baselineBeams[i]?.rate_bps)}));const max=Math.max(1,...rows.flatMap((r)=>[r.required,r.model,r.baseline].filter(Number.isFinite)));const w=640,h=220,left=42,right=12,bottom=30,top=8,band=(w-left-right)/Math.max(1,rows.length);let rects="";rows.forEach((r,i)=>{[r.required,r.model,r.baseline].forEach((v,j)=>{if(!Number.isFinite(v))return;const height=v/max*(h-bottom-top),bw=Math.max(1,Math.min(5,band*.27));rects+=`<rect x="${left+i*band+j*bw}" y="${h-bottom-height}" width="${bw}" height="${height}" fill="${palette[j]}"><title>${esc(r.identity)} · ${["需求（bps）","当前模型（bps）",name+"（bps）"][j]} ${v}</title></rect>`;});});container.innerHTML=`<div class="chart-legend">${["业务需求（bps 原始值）","当前模型速率（bps 原始值）",name+"速率（bps 原始值）"].map((label,i)=>`<span><i style="background:${palette[i]}"></i>${esc(label)}</span>`).join("")}</div><svg role="img" aria-label="同场景逐束业务需求、模型和基线最终速率" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${left}" x2="${w-right}" y1="${h-bottom}" y2="${h-bottom}" stroke="#a8bdc9"/><text x="${left-5}" y="${top+9}" text-anchor="end" fill="#7890a0" font-size="10">${esc(shortNumber(max))}</text>${rects}<text x="${w-right}" y="${h-6}" text-anchor="end" fill="#7890a0" font-size="10">处理顺序 →</text></svg>`;}
function drawBarComparison(container,rows,key1,key2,label1,label2){label1+=speedMetricKeys.has(key1)?"（bps 原始值）":powerMetricKeys.has(key1)?"（W 原始值）":"";if(key2)label2+=speedMetricKeys.has(key2)?"（bps 原始值）":powerMetricKeys.has(key2)?"（W 原始值）":"";const points=rows.map((x)=>({identity:beamIdentity(x),a:Number(x[key1]),b:key2?Number(x[key2]):null})).filter((x)=>Number.isFinite(x.a));if(!points.length){container.innerHTML='<div class="empty-state">没有可绘制的真实记录</div>';return;}const max=Math.max(1,...points.flatMap((x)=>[x.a,x.b??0]));const w=640,h=220,left=42,right=12,bottom=30,top=8,usable=w-left-right,band=usable/points.length;let rects="";points.forEach((p,i)=>{const x=left+i*band,barW=Math.max(1,Math.min(8,band*(key2?.32:.6)));const ah=(p.a/max)*(h-bottom-top),bh=(p.b??0)/max*(h-bottom-top);rects+=`<rect x="${x+band*.1}" y="${h-bottom-ah}" width="${barW}" height="${ah}" fill="${palette[0]}"><title>${esc(p.identity)} · ${label1} ${p.a}</title></rect>`;if(key2)rects+=`<rect x="${x+band*.1+barW+1}" y="${h-bottom-bh}" width="${barW}" height="${bh}" fill="${palette[1]}"><title>${esc(p.identity)} · ${label2} ${p.b}</title></rect>`;});container.innerHTML=`<div class="chart-legend"><span><i style="background:${palette[0]}"></i>${esc(label1)}</span>${key2?`<span><i style="background:${palette[1]}"></i>${esc(label2)}</span>`:""}</div><svg role="img" aria-label="${esc(label1)}${key2?`与${label2}`:""}逐束分布" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${left}" x2="${w-right}" y1="${h-bottom}" y2="${h-bottom}" stroke="#a8bdc9"/><text x="${left-5}" y="${top+9}" text-anchor="end" fill="#7890a0" font-size="10">${esc(shortNumber(max))}</text>${rects}<text x="${w-right}" y="${h-6}" text-anchor="end" fill="#7890a0" font-size="10">处理顺序 →</text></svg>`;}
async function compare(){const run_ids=[...document.querySelectorAll(".compare-choice:checked")].map((x)=>x.value);if(run_ids.length<2){notify("至少选择两个运行",true);return;}try{const data=await api("/api/compare","POST",{run_ids});state.comparison=data;renderComparison(data);renderConfigDifferences(data.runs||[]);notify("配对结果已生成");}catch(error){$("compare-notice").textContent=error.message;$("compare-notice").className="notice bad";$("compare-output").hidden=true;notify(error.message,true);}}
function renderComparison(data){$("compare-output").hidden=false;$("compare-notice").textContent=`已对比 ${data.runs?.length||0} 个运行；请查看配对口径与警告。`;$("compare-notice").className="notice good";$("compare-warnings").innerHTML=(data.warnings||[]).map((x)=>`<div class="notice warn">${esc(x)}</div>`).join("");const rows=data.rows||[];const cols=[...new Set(rows.flatMap((x)=>Object.keys(x)))];$("compare-table").innerHTML=rows.length?`<table class="data-table"><thead><tr>${cols.map((k)=>`<th>${esc(metricHeading(k))}</th>`).join("")}</tr></thead><tbody>${rows.map((r)=>`<tr>${cols.map((k)=>`<td>${esc(r[k]&&typeof r[k]==="object"?JSON.stringify(r[k]):displayMetric(k,r[k]))}</td>`).join("")}</tr>`).join("")}</tbody></table>`:'<div class="empty-state">服务端没有返回配对行；请检查场景和口径警告。</div>';$("compare-configs").innerHTML=(data.runs||[]).map((r)=>`<div><strong>${esc(r.name||r.run_id||r.id||"运行")}</strong>\n${esc(JSON.stringify(r.config||r,null,2))}</div>`).join("");}
function flattenConfig(value,prefix="",out={}){if(value&&typeof value==="object"&&!Array.isArray(value)){for(const [key,item] of Object.entries(value))flattenConfig(item,prefix?`${prefix}.${key}`:key,out);}else out[prefix]=value;return out;}
function renderConfigDifferences(runs){const maps=runs.map((r)=>flattenConfig(r.config||{})),keys=[...new Set(maps.flatMap((m)=>Object.keys(m)))].filter((key)=>new Set(maps.map((m)=>JSON.stringify(m[key]))).size>1);$("compare-configs").innerHTML=`<div class="config-diff"><h3>配置差异</h3>${keys.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>配置项</th>${runs.map((r)=>`<th>${esc(r.name||r.run_id)}</th>`).join("")}</tr></thead><tbody>${keys.map((key)=>`<tr><td>${esc(key)}</td>${maps.map((m)=>`<td>${esc(JSON.stringify(m[key]??"—"))}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`:'<p class="muted small">所选运行的配置字段相同。</p>'}</div>`;}
function downloadJson(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function saveConfig(){if(!await validate(false)){notify("请先修正配置错误",true);return;}try{const result=await api("/api/configs","POST",{name:state.config.name,config:state.validated.config});notify(`方案已保存${result.id?`：${result.id}`:""}`);}catch(error){notify(error.message,true);}}
async function startTraining(){if(state.requestBusy)return;state.requestBusy=true;$("config-start").disabled=true;try{if(!await validate(false)){notify("配置未通过校验，无法提交",true);return;}const payload={config:clone(state.validated.config),...(state.trainingSceneId?{scene_id:state.trainingSceneId}:{}),...(state.validationSceneId?{validation_scene_id:state.validationSceneId}:{}),...(state.testSceneId?{test_scene_id:state.testSceneId}:{})};const pending=pendingRequest(pendingTrainKey,payload);const result=await api("/api/runs","POST",{...pending.payload,request_id:pending.request_id});if(!result.run_id)throw new Error("服务未返回训练运行编号，可用原请求编号重试");clearPendingRequest(pendingTrainKey,pending.request_id);state.selectedRun=result.run_id;notify(`训练任务已提交：${result.run_id}`);setPage("monitor");}catch(error){notify(`${error.message}；如提交结果不确定，请再次点击以复用请求编号`,true);}finally{state.requestBusy=false;$("config-start").disabled=false;}}
async function refreshSceneCatalog(){try{const data=await api("/api/scenes");state.scenes=data.scenes||[];if(state.config){clearIncompatibleSceneSelections();if(state.configTab==="training")renderConfigForm();}}catch(error){notify(error.message,true);}}
async function loadSavedConfigs(){try{const data=await api("/api/configs"),list=data.configs||[];options($("saved-config-select"),list,(x)=>x.name||x.id,(x)=>x.id,"选择方案");$("config-dialog").showModal();$("config-dialog")._items=list;}catch(error){notify(error.message,true);}}
function wire(){$("aviation-import").addEventListener("click",importAviationScenes);document.querySelectorAll("[data-page]").forEach((x)=>x.addEventListener("click",()=>setPage(x.dataset.page)));document.querySelectorAll("[data-config-tab]").forEach((x)=>x.addEventListener("click",()=>{state.configTab=x.dataset.configTab;renderConfigForm();}));$("config-name").addEventListener("input",(e)=>{state.config.name=e.target.value;saveDraft();scheduleValidation();});$("config-algorithm").addEventListener("change",(e)=>{state.config.algorithm=e.target.value;renderConfigForm();saveDraft();scheduleValidation();});$("config-form").addEventListener("change",(e)=>onConfigInput(e.target));$("config-form").addEventListener("input",(e)=>{if(e.target.matches("[data-path],[data-term-weight],[data-term-scale]"))onConfigInput(e.target);});$("config-validate").addEventListener("click",()=>validate());$("config-save").addEventListener("click",saveConfig);$("config-start").addEventListener("click",startTraining);$("config-export").addEventListener("click",()=>state.config&&downloadJson(`${(state.config.name||"实验配置").replace(/[\\/:*?"<>|]/g,"_")}.json`,state.config));$("config-import").addEventListener("click",()=>$("config-file").click());$("config-file").addEventListener("change",async(e)=>{try{const file=e.target.files?.[0];if(!file)return;state.config=JSON.parse(await file.text());renderConfigForm();saveDraft();await validate();}catch(error){notify("导入失败："+error.message,true);}finally{e.target.value="";}});$("config-load").addEventListener("click",loadSavedConfigs);$("saved-config-apply").addEventListener("click",()=>{const item=$("config-dialog")._items?.find((x)=>String(x.id)===$("saved-config-select").value);if(item){state.config=clone(item.config||item);renderConfigForm();saveDraft();scheduleValidation();}});$("system-refresh").addEventListener("click",refreshSystem);$("monitor-run").addEventListener("change",()=>{state.selectedRun=$("monitor-run").value;refreshMonitor();});$("monitor-refresh").addEventListener("click",refreshMonitor);for(const key of ["chart-axis","chart-smooth","chart-show-raw","chart-show-smooth"])$(key).addEventListener("change",()=>{renderCharts(state.metrics||{});renderTagBrowser(state.metrics||{});});$("tag-search").addEventListener("input",()=>renderTagBrowser(state.metrics||{}));$("tag-select").addEventListener("change",()=>renderTagBrowser(state.metrics||{}));$("monitor-stop").addEventListener("click",()=>runAction("stop"));$("monitor-resume").addEventListener("click",()=>runAction("resume"));$("monitor-download").addEventListener("click",()=>{const run=state.selectedRun;if(run)window.location.href=`/api/runs/${encodeURIComponent(run)}/download?file=metrics.jsonl`;});$("test-refresh").addEventListener("click",refreshResources);$("model-select").addEventListener("change",renderSelectionDetails);$("scene-select").addEventListener("change",renderSelectionDetails);$("model-import").addEventListener("click",importModel);$("scene-generate").addEventListener("click",()=>createScene(false));$("scene-import").addEventListener("click",()=>createScene(true));$("test-start").addEventListener("click",startEvaluation);$("evaluation-load").addEventListener("click",loadEvaluation);$("result-scene").addEventListener("change",renderSceneResult);$("compare-refresh").addEventListener("click",refreshRuns);$("compare-run").addEventListener("click",compare);$("compare-export").addEventListener("click",()=>state.comparison&&downloadJson("配对结果.json",state.comparison));window.addEventListener("hashchange",()=>{const name=location.hash.slice(1);if(["config","monitor","test","compare"].includes(name))setPage(name);});}
async function runAction(action){if(!state.selectedRun)return;try{await api(`/api/runs/${encodeURIComponent(state.selectedRun)}/${action}`,"POST",{});notify(action==="stop"?"已请求安全停止并保存":"已请求从断点恢复");refreshMonitor();}catch(error){notify(error.message,true);}}
async function init(){wire();$("config-form").addEventListener("click",(event)=>{const button=event.target.closest("[data-move-feature]");if(button)moveFeature(button.dataset.moveFeature,Number(button.dataset.direction));});$("network-graph").addEventListener("click",(event)=>{const button=event.target.closest("[data-network-branch]");if(button){state.selectedBranch=button.dataset.networkBranch;renderNetworkGraph();}});document.querySelector('[data-config-tab="training"]').addEventListener("click",refreshSceneCatalog);$("monitor-overlay").addEventListener("change",refreshMonitor);$("monitor-download").addEventListener("click",(event)=>{event.stopImmediatePropagation();const run=state.selectedRun,file=$("monitor-file").value;if(run&&file)window.location.href=`/api/runs/${encodeURIComponent(run)}/download?file=${encodeURIComponent(file)}`;},true);$("model-download").addEventListener("click",()=>{const id=$("model-select").value;if(!id){notify("请先选择模型",true);return;}window.location.href=`/api/models/${encodeURIComponent(id)}/download`;});for(const [button,file] of [["test-report-download","report.md"],["test-csv-download","beam_results.csv"],["test-json-download","results.json"]])$(button).addEventListener("click",()=>{const run=$("evaluation-run").value;if(run)window.location.href=`/api/runs/${encodeURIComponent(run)}/download?file=${encodeURIComponent(file)}`;});$("baseline-view").addEventListener("change",renderSceneResult);$("trace-prev").addEventListener("click",()=>setTraceIndex(state.traceIndex-1));$("trace-next").addEventListener("click",()=>setTraceIndex(state.traceIndex+1));$("trace-step").addEventListener("input",(event)=>setTraceIndex(Number(event.target.value)));try{const data=await api("/api/catalog");state.catalog=data;state.defaults=data.defaults||data.default_config;if(!state.defaults)throw new Error("服务未提供默认配置");state.config=loadDraft()||clone(state.defaults);renderConfigForm();await validate(false);}catch(error){$("config-errors").textContent=error.message;$("config-errors").className="notice bad";notify(error.message,true);}await Promise.allSettled([refreshSystem(),refreshRuns(),refreshSceneCatalog()]);const page=location.hash.slice(1);if(["config","monitor","test","compare"].includes(page))setPage(page);state.poll=setInterval(()=>{if(state.page==="monitor")refreshMonitor();else if(state.page==="test"&&$("evaluation-run").value)loadEvaluation();},7000);}
document.addEventListener("DOMContentLoaded",init);
